import{_ as d,C as e,o,c as r,j as t,a as p,E as s,a3 as h}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"坐忘论·真观","description":"坐忘论第五篇精读（上/下合并）：由无欲观妙，于衣食而不贪、于色境而不著；观贫病生死，从「被境所困」转为「以境炼心」。","frontmatter":{"title":"坐忘论·真观","description":"坐忘论第五篇精读（上/下合并）：由无欲观妙，于衣食而不贪、于色境而不著；观贫病生死，从「被境所困」转为「以境炼心」。","category":"guide","aliases":["坐忘论真观","真观五","坐忘论精读之六"],"source":["坐忘论","司马承祯"],"outline":[2,3]},"headers":[],"relativePath":"daoism/daoist-classics/zuowang-lun/chapter-05.md","filePath":"daoism/daoist-classics/zuowang-lun/chapter-05.md","lastUpdated":1789714390000}'),c={name:"daoism/daoist-classics/zuowang-lun/chapter-05.md"};function g(b,a,u,v,m,x){const i=e("DaoReadingPrelude"),n=e("DaoTextReading"),l=e("DaoKeywordCards");return o(),r("div",null,[a[0]||(a[0]=t("h1",{id:"坐忘论·真观",tabindex:"-1"},[p("坐忘论·真观 "),t("a",{class:"header-anchor",href:"#坐忘论·真观","aria-label":'Permalink to "坐忘论·真观"'},"​")],-1)),s(i,{title:"观本知末，又非躁竞之情",summary:"收心使心不随念头散乱，简事使形神不为万事耗损；真观进一步追问：我们为什么会被某种境界吸引、排斥或困扰？这层爱恶所依赖的判断，究竟真实可靠吗？它不是观看异象，也不是预测吉凶。",points:[{label:"先立观",text:"收心简事，日损有为，体静心闲，方可观妙。"},{label:"次观境",text:"衣食如船、色由想起、善恶不引为己病、贫病生死皆可观。"},{label:"后辨心",text:"「合境之心观境」终身不觉有恶；须以「离境之心」才见是非。"}],hint:"本篇较长，按所观对象分为六节。可与《天隐子·存想》对读：一篇收心，一篇观理。"}),a[1]||(a[1]=t("h2",{id:"【原典层】原文",tabindex:"-1"},[p("【原典层】原文 "),t("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),a[2]||(a[2]=t("p",null,[t("strong",null,"一、何谓真观")],-1)),s(n,{paragraphs:["夫真观者，智士之先鉴，能人之善察，究傥来之祸福，详动静之吉凶，得见机前，因之造适，深祈卫足，窃务全生，自始至末，行无遗累，理不违此者，谓之真观。","然一餐一寝，俱为损益之源，一行一言，堪成祸福之本。","虽作巧持其末，不如拙诫其本。观本知末，又非躁竞之情。","是故收心简事，日损有为，体静心闲，方可观妙。","经云：常无欲，以观其妙。","然修道之身，必资衣食，事有不可废，物有不可弃者，当须虚襟而受之，明目而当之，勿以为妨，心生烦躁。若因事烦躁者，心病已动，何名安心？"]}),a[3]||(a[3]=t("p",null,[t("strong",null,"二、衣食如船舫")],-1)),s(n,{paragraphs:["夫人事衣食者，我之船舫也。欲渡于海，事资船舫，渡海若讫，理自不留。因何未渡，先欲废舍？","衣食虚幻，实不足营，为出离虚幻，故求衣食，虽有营求之事，莫生得失之心，即有事无事，心常安泰。","与物同求而不同贪，与物同得而不同积，不贪故无忧，不积故无失，迹每同人，心常异俗。此实行之宗要，可力为之。"]}),a[4]||(a[4]=t("p",null,[t("strong",null,"三、观色欲")],-1)),s(n,{paragraphs:["前虽断简，病有难除者，但依法观之。","若色病重者，当观染色都由想尔，想若不生，终无色事。当知色想外空，色心内妄，妄想心空，谁为色主？","经云：色者，想尔想悉是空，何有色也？","又思妖妍美色，甚于狐魅，狐魅媚人，令人厌患，虽身致死，不入恶道，为厌患故，永离邪淫。","妖艳惑人，令人爱著，乃致身死，留恋弥深，为邪念故，死堕诸趣，生地狱中。","故经云：今代发心为夫妻，死后不得俱生人道。所以者何？为邪念故。","又观色若定是美，何故鱼见深入，鸟见高飞，仙人观之为秽浊，贤人喻之为刀斧？","一生之命，七日不食，便至于死，百年无色，翻免夭伤。故知色者非身心之要，适为性命之仇贼，何须系著，自取消毁。"]}),a[5]||(a[5]=t("p",null,[t("strong",null,"四、观他人善恶")],-1)),s(n,{paragraphs:["若见他人为恶，心生嫌恶者，犹如见人自杀，己身引颈，乘取他刀以自害命。","他自为恶不遣，我当何故引取他恶，以为己病。","又见为恶者若可嫌，见为善者亦须恶。何以然耶？同障道故。"]}),a[6]||(a[6]=t("p",null,[t("strong",null,"五、观贫病")],-1)),s(n,{paragraphs:["若贫者亦审观之，谁与我贫？天地平等，覆载无私，我今贫苦，非天地也。父母生子，欲令富贵，我今贫贱，非父母也。人及鬼神，自救无暇，何能有力将贫与我？进退寻察，无所从来，乃知我业也，乃知天命也。","业由我造，命由天赋，业之与命，犹影响之逐形声。既不可逃，又不可怨，唯有智者善而达之，乐天知命，故不忧，何贫之可苦也。","庄云：业入而不可舍。为自业故，贫病来入，不可舍止。","经云：天地不能改其操，阴阳不能回其业。由此言之，故真命也，非假物耳，有何怨焉？","又如勇士逢贼，无所畏惧，挥剑当前，群寇皆溃，功勋一立，荣禄终身。今有贫病恼乱我身，则寇贼也，我有正心，则勇士也，用智观察，则挥剑也，恼累消除，则战胜也，湛然常乐，则荣禄也。","凡有苦事来迫，我心不以此观而生忧累，则如人逢贼不立功勋，弃甲背军，逃亡获罪，去乐就苦，何可悯焉？","若病苦者，当观此病由有我身，若无我身，患无所托。","经云：及吾无身，吾有何患。","次观于心，亦无真宰，内外求觅，无能受者，所有计念，从妄心生。然枯形灰心，则万病俱泯。"]}),a[7]||(a[7]=t("p",null,[t("strong",null,"六、观生死与总归")],-1)),s(n,{paragraphs:["若恶死者，应思我身是神之舍，身今老病，气力衰微，如屋朽坏，不堪居止，自须舍离，别处求安。身死神逝，亦复如是。","若恋生恶死，拒违变化，则神识错乱，失其正业。以此托生，受气之际，不感清秀，多逢浊辱。盖下愚贪鄙，实此之由。","若当生不悦，顺死不恶者，一为生死理齐，二为后身成业。","若贪爱万境，一爱一病。一肢有病，犹令举体不安；况一心万病，身欲长生，岂可得乎？","凡有爱恶，皆是妄生，积妄不除，以妨见道。是故须舍诸欲，住无所有，徐清有本，然后返观旧所爱处，自生厌薄。","若以合境之心观境，终身不觉有恶。如将离境之心观境，方能了见是非。譬如醒人能观醉者为恶，如其自醉不觉其非。","经云：吾本弃俗，厌离世间。又云：耳目声色，为子留愆，鼻口所喜，香味是怨。老君厌世弃俗，独见香味是怨，嗜欲之流，焉知鲍肆为臭哉。"]}),a[8]||(a[8]=t("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),t("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(l,{items:[{term:"先鉴",pinyin:["xiān","jiàn"],meaning:"在结果完全出现以前便有所鉴察。非无根据地预知未来，而是从已存在的细微征兆看见可能的后果。"},{term:"善察",pinyin:["shàn","chá"],meaning:"善于辨别细微的原因、倾向与后果。"},{term:"傥来",pinyin:["tǎng","lái"],meaning:"偶然而来、忽然而至。近《庄子》「物之傥来，寄者也」之义：得失常因条件暂时聚合，非可永久占有。"},{term:"见机前",pinyin:["jiàn","jī","qián"],meaning:"机，事物变化的细微开端。谓在结果充分形成以前看见其趋势，并据此调整。"},{term:"造适",pinyin:["zào","shì"],meaning:"采取适当行动，使之趋向合宜。"},{term:"卫足",pinyin:["wèi","zú"],meaning:"保全自身，不使自己陷入危险；亦有谨慎自守、不使性命受损之意。"},{term:"遗累",pinyin:["yí","lěi"],meaning:"遗留的牵累。行无遗累，谓从开始到结束都不留下后续负担——这是判断真观的重要标准。"},{term:"巧持其末",pinyin:["qiǎo","chí","qí","mò"],meaning:"用高明技巧挽救事情的末端后果。与其如此，不如「拙诫其本」——在起点上谨慎防范。本篇明确贵拙而抑巧。"},{term:"虚襟",pinyin:["xū","jīn"],meaning:"心胸虚静，不以贪爱占有。对必要之衣食，「虚襟而受之，明目而当之」。"},{term:"船舫",pinyin:["chuán","fǎng"],meaning:"船。人事衣食如渡海之船：是工具而非终点；未渡不可先舍，渡讫则理自不留。"},{term:"想尔",pinyin:["xiǎng","ěr"],meaning:"想，心的构画标记。染色都由想尔，谓对美色的染著主要由心的想象、命名与反复加工形成。"},{term:"狐魅",pinyin:["hú","mèi"],meaning:"古代关于精怪魅惑人的文化想象。本篇以美色甚于狐魅为喻：狐魅令人厌患，美色却令人主动爱著。"},{term:"诸趣",pinyin:["zhū","qù"],meaning:"佛教语，指六道众生所趣之处。原文以「死堕诸趣」为业报警示。"},{term:"真宰",pinyin:["zhēn","zǎi"],meaning:"语本《庄子·齐物论》「必有真宰，而特不得其朕」。此处谓内外求觅，找不到一个独立不变、专门承受苦患的主宰。"},{term:"枯形灰心",pinyin:["kū","xíng","huī","xīn"],meaning:"对形体的执著如枯木般不再繁兴，妄动之心如死灰般寂静。与《泰定》「形如槁木，心若死灰」相近。"},{term:"合境之心",pinyin:["hé","jìng","zhī","xīn"],meaning:"已与境界黏合、认同、沉迷的心。以此观境，终身不觉有恶。"},{term:"离境之心",pinyin:["lí","jìng","zhī","xīn"],meaning:"已开始离开、不再完全认同那个境界的心。以此观境，方能了见是非。本篇真观之要害。"},{term:"鲍肆",pinyin:["bào","sì"],meaning:"卖腌鱼、咸鱼的店铺，气味浓重。古以「久入鲍鱼之肆，不闻其臭」喻久处不良环境而渐不自觉。"}]}),a[9]||(a[9]=h("",205))])}const C=d(c,[["render",g]]);export{y as __pageData,C as default};
